{"step_index":2620,"source":"MODEL","type":"VIEW_FILE","status":"DONE","created_at":"2026-07-23T18:43:21Z","content":"Created At: 2026-07-23T21:43:21+03:00\nCompleted At: 2026-07-23T21:43:21+03:00\nFile Path: `file:///C:/Users/ensar/Downloads/NEXUS-AI/packages/i18n/src/index.ts`\nTotal Lines: 214\nTotal Bytes: 8186\nShowing lines 1 to 214\nThe following code has been modified to include a line number before every line, in the format: <line_number>: <original_line>. Please note that any changes targeting the original code should remove the line number, colon, and leading space.\n1: /**\n2:  * NEXUS AI — Internationalization (FAZ 13)\n3:  *\n4:  * Message catalogs, locale resolution and locale-aware formatting. All\n5:  * user-facing text is looked up by key so the interface, AI responses and\n6:  * voice layer stay consistent when the language changes (FAZ 13 Bitiş Kriteri).\n7:  *\n8:  * Also resolves a browser `Accept-Language` header to a supported locale, which\n9:  * the web Download Center uses to open in the visitor's language automatically\n10:  * (FAZ 10 ↔ FAZ 18 link). Uses the platform Intl API for number/date/currency,\n11:  * so multi-currency and regional formats work without extra dependencies.\n12:  */\n13: \n14: export type Locale = \"en\" | \"tr\";\n15: export const SUPPORTED_LOCALES: readonly Locale[] = [\"en\", \"tr\"];\n16: export const DEFAULT_LOCALE: Locale = \"en\";\n17: \n18: export type MessageKey =\n19:   | \"app.greeting\"\n20:   | \"app.confirmNeeded\"\n21:   | \"download.title\"\n22:   | \"download.primaryButton\"\n23:   | \"download.otherOs\"\n24:   | \"download.checksum\"\n25:   | \"screen.today\"\n26:   | \"screen.homeState\"\n27:   | \"screen.suggestions\"\n28:   | \"screen.skills\"\n29:   | \"screen.family\"\n30:   | \"screen.devices\"\n31:   | \"screen.personalization\"\n32:   | \"screen.billing\"\n33:   | \"screen.downloadCenter\"\n34:   | \"today.devicesOnline\"\n35:   | \"today.energy\"\n36:   | \"today.activeRoutines\"\n37:   | \"today.suggestions\"\n38:   | \"screen.devices.empty\"\n39:   | \"screen.suggestions.empty\"\n40:   | \"screen.skills.empty\"\n41:   | \"screen.homeState.empty\"\n42:   | \"plan.free\"\n43:   | \"plan.premium\"\n44:   | \"plan.family\"\n45:   | \"billing.manage\"\n46:   // Dynamic keys added from mock data\n47:   | \"Dim living room lights\"\n48:   | \"Start morning news briefing\"\n49:   | \"Movie night\"\n50:   | \"Good morning\"\n51:   | \"Leaving home\"\n52:   | \"status.pctOnline\"\n53:   | \"status.offlineCount\"\n54:   | \"status.allOnline\"\n55:   | \"status.suggestionReady\"\n56:   | \"status.suggestionsReady\"\n57:   | \"status.caughtUp\"\n58:   | \"status.onlineOfTotal\";\n59: \n60: type Catalog = Record<MessageKey, string>;\n61: \n62: export const CATALOGS: Record<Locale, Catalog> = {\n63:   en: {\n64:     \"app.greeting\": \"Hi {name}, how can I help?\",\n65:     \"app.confirmNeeded\": \"{name}, that action needs your confirmation.\",\n66:     \"download.title\": \"Download NEXUS\",\n67:     \"download.primaryButton\": \"Download for {os}\",\n68:     \"download.otherOs\": \"Using a different operating system?\",\n69:     \"download.checksum\": \"SHA-256 checksum\",\n70:     \"screen.today\": \"Today\",\n71:     \"screen.homeState\": \"Home\",\n72:     \"screen.suggestions\": \"Suggestions\",\n73:     \"screen.skills\": \"Skills\",\n74:     \"screen.family\": \"Family\",\n75:     \"screen.devices\": \"Devices\",\n76:     \"screen.personalization\": \"Personalization\",\n77:     \"screen.billing\": \"Subscription\",\n78:     \"screen.downloadCenter\": \"Download\",\n79:     \"today.devicesOnline\": \"Devices online\",\n80:     \"today.energy\": \"Energy today\",\n81:     \"today.activeRoutines\": \"Active routines\",\n82:     \"today.suggestions\": \"Suggestions\",\n83:     \"screen.devices.empty\": \"No devices connected yet.\",\n84:     \"screen.suggestions.empty\": \"No suggestions yet — NEXUS AI is still learning.\",\n85:     \"screen.skills.empty\": \"No skills learned yet.\",\n86:     \"screen.homeState.empty\": \"No rooms with devices yet.\",\n87:     \"plan.free\": \"Free\",\n88:     \"plan.premium\": \"Premium\",\n89:     \"plan.family\": \"Family\",\n90:     \"billing.manage\": \"Manage subscription\",\n91:     \"Dim living room lights\": \"Dim living room lights\",\n92:     \"Start morning news briefing\": \"Start morning news briefing\",\n93:     \"Movie night\": \"Movie night\",\n94:     \"Good morning\": \"Good morning\",\n95:     \"Leaving home\": \"Leaving home\",\n96:     \"status.pctOnline\": \"{pct}% online\",\n97:     \"status.offlineCount\": \"{count} offline\",\n98:     \"status.allOnline\": \"All devices online\",\n99:     \"status.suggestionReady\": \"{count} suggestion ready for you.\",\n100:     \"status.suggestionsReady\": \"{count} suggestions ready for you.\",\n101:     \"status.caughtUp\": \"You're all caught up.\",\n102:     \"status.onlineOfTotal\": \"{online}/{total} online\"\n103:   },\n104:   tr: {\n105:     \"app.greeting\": \"Merhaba {name}, nasıl yardımcı olabilirim?\",\n106:     \"app.confirmNeeded\": \"{name}, bu işlem için onayın gerekiyor.\",\n107:     \"download.title\": \"NEXUS'u İndir\",\n108:     \"download.primaryButton\": \"{os} için indir\",\n109:     \"download.otherOs\": \"Farklı bir işletim sistemi mi kullanıyorsun?\",\n110:     \"download.checksum\": \"SHA-256 sağlama değeri\",\n111:     \"screen.today\": \"Bugün\",\n112:     \"screen.homeState\": \"Ev\",\n113:     \"screen.suggestions\": \"Öneriler\",\n114:     \"screen.skills\": \"Yetenekler\",\n115:     \"screen.family\": \"Aile\",\n116:     \"screen.devices\": \"Cihazlar\",\n117:     \"screen.personalization\": \"Kişiselleştirme\",\n118:     \"screen.billing\": \"Abonelik\",\n119:     \"screen.downloadCenter\": \"İndirme Merkezi\",\n120:     \"today.devicesOnline\": \"Çevrimiçi cihazlar\",\n121:     \"today.energy\": \"Bugünkü enerji\",\n122:     \"today.activeRoutines\": \"Aktif rutinler\",\n123:     \"today.suggestions\": \"Öneriler\",\n124:     \"screen.devices.empty\": \"Henüz bağlanan cihaz yok.\",\n125:     \"screen.suggestions.empty\": \"Henüz öneri yok — NEXUS AI hâlâ öğreniyor.\",\n126:     \"screen.skills.empty\": \"Henüz öğrenilen bir yetenek yok.\",\n127:     \"screen.homeState.empty\": \"Henüz cihaz eklenmiş bir oda yok.\",\n128:     \"plan.free\": \"Ücretsiz\",\n129:     \"plan.premium\": \"Premium\",\n130:     \"plan.family\": \"Aile\",\n131:     \"billing.manage\": \"Aboneliği yönet\",\n132:     \"Dim living room lights\": \"Oturma odası ışıklarını kıs\",\n133:     \"Start morning news briefing\": \"Sabah haber bültenini başlat\",\n134:     \"Movie night\": \"Film gecesi\",\n135:     \"Good morning\": \"Günaydın\",\n136:     \"Leaving home\": \"Evden ayrılış\",\n137:     \"status.pctOnline\": \"%{pct} çevrimiçi\",\n138:     \"status.offlineCount\": \"{count} çevrimdışı\",\n139:     \"status.allOnline\": \"Tüm cihazlar çevrimiçi\",\n140:     \"status.suggestionReady\": \"Senin için {count} öneri hazır.\",\n141:     \"status.suggestionsReady\": \"Senin için {count} öneri hazır.\",\n142:     \"status.caughtUp\": \"Her şey yolunda.\",\n143:     \"status.onlineOfTotal\": \"{online}/{total} çevrimiçi\"\n144:   },\n145: };\n146: \n147: /** Narrow any string to a supported Locale, falling back to the default. */\n148: export function resolveLocale(input: string | undefined | null): Locale {\n149:   if (!input) return DEFAULT_LOCALE;\n150:   const base = input.trim().toLowerCase().split(\"-\")[0];\n151:   return (SUPPORTED_LOCALES as readonly string[]).includes(base ?? \"\")\n152:     ? (base as Locale)\n153:     : DEFAULT_LOCALE;\n154: }\n155: \n156: /**\n157:  * Pick the best supported locale from an HTTP `Accept-Language` header, honoring\n158:  * the client's quality (q) ordering. Used by the Download Center auto-language.\n159:  */\n160: export function resolveFromAcceptLanguage(header: string | undefined | null): Locale {\n161:   if (!header) return DEFAULT_LOCALE;\n162:   const ranked = header\n163:     .split(\",\")\n164:     .map((part) => {\n165:       const [tag, ...params] = part.trim().split(\";\");\n166:       const q = params.find((p) => p.startsWith(\"q=\"));\n167:       const quality = q ? Number.parseFloat(q.slice(2)) : 1;\n168:       return { tag: (tag ?? \"\").toLowerCase(), quality: Number.isNaN(quality) ? 0 : quality };\n169:     })\n170:     .sort((a, b) => b.quality - a.quality);\n171: \n172:   for (const { tag } of ranked) {\n173:     const base = tag.split(\"-\")[0] ?? \"\";\n174:     if ((SUPPORTED_LOCALES as readonly string[]).includes(base)) return base as Locale;\n175:   }\n176:   return DEFAULT_LOCALE;\n177: }\n178: \n179: function interpolate(template: string, vars: Record<string, string | number>): string {\n180:   return template.replace(/\\{(\\w+)\\}/g, (_, k: string) => (k in vars ? String(vars[k]) : `{${k}}`));\n181: }\n182: \n183: /** Translate a key for a locale, with {placeholder} interpolation. */\n184: export function translate(\n185:   locale: Locale,\n186:   key: MessageKey,\n187:   vars: Record<string, string | number> = {},\n188: ): string {\n189:   const catalog = CATALOGS[locale] ?? CATALOGS[DEFAULT_LOCALE];\n190:   return interpolate(catalog[key], vars);\n191: }\n192: \n193: /** A bound translator for a single locale (convenience for UI layers). */\n194: export function createTranslator(locale: Locale) {\n195:   return (key: MessageKey, vars?: Record<string, string | number>) => translate(locale, key, vars);\n196: }\n197: \n198: const INTL_LOCALE: Record<Locale, string> = { en: \"en-US\", tr: \"tr-TR\" };\n199: \n200: export function formatNumber(locale: Locale, value: number): string {\n201:   return new Intl.NumberFormat(INTL_LOCALE[locale]).format(value);\n202: }\n203: \n204: export function formatCurrency(locale: Locale, value: number, currency: string): string {\n205:   return new Intl.NumberFormat(INTL_LOCALE[locale], { style: \"currency\", currency }).format(value);\n206: }\n207: \n208: export function formatDate(locale: Locale, date: Date): string {\n209:   return new Intl.DateTimeFormat(INTL_LOCALE[locale], { dateStyle: \"long\" }).format(date);\n210: }\n211: \n212: export const moduleName = \"i18n\" as const;\n213: export const implemented = true;\n214: \nThe above content shows the entire, complete file contents of the requested file.\n"}
